from report import keyword_report, page_report


def test_counts_and_shares():
    result = keyword_report("the cat and the hat and the bat", k=2)
    assert result["count"] == 8
    assert result["top"] == [("the", 3, 0.375), ("and", 2, 0.25)]


def test_ties_break_by_word_order():
    result = keyword_report("pear apple pear apple plum", k=2)
    assert result["top"] == [("apple", 2, 0.4), ("pear", 2, 0.4)]


def test_empty_text():
    assert keyword_report("", k=3) == {"count": 0, "top": []}


def test_stopwords_can_be_dropped():
    result = keyword_report("the cat and the cat hat", k=2, drop_stopwords=True)
    assert result["count"] == 3
    assert result["top"] == [("cat", 2, 0.6667), ("hat", 1, 0.3333)]


def test_dropping_stopwords_can_empty_the_text():
    assert keyword_report("the and of", k=2, drop_stopwords=True) == {"count": 0, "top": []}


def test_paging_splits_the_top_list():
    text = "alpha alpha alpha beta beta gamma"
    assert page_report(text, k=3, size=2) == [
        [("alpha", 3, 0.5), ("beta", 2, 0.3333)],
        [("gamma", 1, 0.1667)],
    ]

"""关键词报告对外接口。"""

import filters
import paging
import ranking
import tokenizer


def keyword_report(text, k=3, drop_stopwords=False):
    """给出文本中出现次数最多的前 k 个词及其占比。

    占比按参与统计的词元总数计算并保留四位小数。drop_stopwords 为真时先去掉停用词。
    参与统计的词元为空时返回总数零与空列表。
    """
    words = tokenizer.tokenize(text)
    if drop_stopwords:
        words = filters.keep(words)
    if not words:
        return {"count": 0, "top": []}
    top = ranking.ranked(ranking.counts(words), k)
    return {"count": len(words),
            "top": [(w, n, round(n / len(words), 4)) for w, n in top]}


def page_report(text, k=3, size=2, drop_stopwords=False):
    """给出报告并按 size 分页，返回每页的词项列表。"""
    top = keyword_report(text, k, drop_stopwords)["top"]
    pages = paging.page_count(len(top), size)
    return [paging.page(top, number, size) for number in range(1, pages + 1)]

"""词频排序。"""


def counts(words):
    """统计每个词的出现次数。"""
    table = {}
    for word in words:
        table[word] = table.get(word, 0) + 1
    return table


def order(item):
    """排序键。"""
    word, n = item
    return (n, word)


def ranked(table, k):
    """取前 k 项，按次数降序、同次按词形升序。"""
    return sorted(table.items(), key=order, reverse=True)[:k]

"""结果分页。"""


def page(items, number, size):
    """取第 number 页，页码从 1 开始。越界返回空列表。"""
    start = (number - 1) * size
    return list(items[start:start + size])


def page_count(total, size):
    """总页数。页大小非正时抛 ValueError。"""
    if size <= 0:
        raise ValueError("页大小必须为正")
    return (total + size - 1) // size

